import { cn } from "@/lib/utils";
import {
  LOGO_NAME_PATH,
  LOGO_SUB_PATH,
  LOGO_VIEWBOX,
  MONO_FRAME,
  MONO_PLINTH,
  MONO_STROKES,
} from "./logo-paths";
import { siteConfig } from "@/config/site";

type Tone = "light" | "dark";

/**
 * Inline vector logo — identical artwork to /public/images/brand/*.svg
 * (generated by scripts/build-logo.py). Inline so colours can adapt to
 * the background without an extra request.
 *
 * tone="dark"  → navy wordmark, for light backgrounds
 * tone="light" → ivory wordmark, for dark backgrounds
 */
export function Logo({ tone = "dark", className, markOnly = false }: { tone?: Tone; className?: string; markOnly?: boolean }) {
  const word = tone === "dark" ? "var(--color-navy)" : "var(--color-ivory)";
  const gold = "var(--color-gold)";
  const mark = (
    <g fill="none" stroke={gold} strokeLinecap="square">
      <g strokeWidth={2.4}>
        {MONO_STROKES.map((d) => (
          <path key={d} d={d} />
        ))}
      </g>
      <path d={MONO_FRAME} strokeWidth={1.2} />
      <path d={MONO_PLINTH} strokeWidth={1.2} />
    </g>
  );
  if (markOnly) {
    return (
      <svg viewBox="0 0 48 60" className={cn("h-10 w-auto", className)} role="img" aria-label={siteConfig.name}>
        {mark}
      </svg>
    );
  }
  return (
    <svg viewBox={LOGO_VIEWBOX} className={cn("h-11 w-auto", className)} role="img" aria-label={siteConfig.name}>
      {mark}
      <path d="M56 10V50" stroke={gold} strokeWidth={0.8} />
      <path fill={word} d={LOGO_NAME_PATH} />
      <path fill={gold} d={LOGO_SUB_PATH} />
    </svg>
  );
}
